def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Non-overlapping, add new interval
                merged.append([start, end])

        return merged

    # Merge both a and b to get canonical forms
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    # For each interval in a_merged, subtract all intervals in b_merged
    result = []

    for a_start, a_end in a_merged:
        # Start with the full interval
        current_intervals = [[a_start, a_end]]

        # Subtract each b interval
        for b_start, b_end in b_merged:
            new_intervals = []

            for c_start, c_end in current_intervals:
                # Check if b interval overlaps with current interval
                if b_end <= c_start or b_start >= c_end:
                    # No overlap, keep the interval
                    new_intervals.append([c_start, c_end])
                else:
                    # There is overlap
                    # Keep the part before b_start
                    if c_start < b_start:
                        new_intervals.append([c_start, b_start])
                    # Keep the part after b_end
                    if b_end < c_end:
                        new_intervals.append([b_end, c_end])

            current_intervals = new_intervals

        result.extend(current_intervals)

    # Merge adjacent intervals in result (they should already be in order)
    return merge_intervals(result)

